#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

#define MAX 1000

typedef struct {
    int x, y, state;
} Node;

int dist[MAX][MAX][2];
int dx[] = {1, -1, 0, 0};
int dy[] = {0, 0, 1, -1};

int main() {
    int M, N;
    scanf("%d %d", &M, &N);

    // 0 = closed east-west, open north-south (initial)
    // 1 = open east-west, closed north-south (toggled)

    for (int i = 0; i < M; i++)
        for (int j = 0; j < N; j++)
            for (int k = 0; k < 2; k++)
                dist[i][j][k] = INT_MAX;

    // 0-1 BFS using deque
    Node deque[MAX * MAX * 2];
    int front = 0, back = 0;

    dist[0][0][0] = 0;
    deque[back++] = (Node){0, 0, 0};

    while (front < back) {
        Node cur = deque[front++];
        int x = cur.x, y = cur.y, s = cur.state;
        int d = dist[x][y][s];

        // Option 1: press switch (takes 1 minute)
        int ns = s ^ 1;
        if (d + 1 < dist[x][y][ns]) {
            dist[x][y][ns] = d + 1;
            deque[back++] = (Node){x, y, ns};
        }

        // Option 2: move to adjacent room
        for (int i = 0; i < 4; i++) {
            int nx = x + dx[i];
            int ny = y + dy[i];

            if (nx < 0 || nx >= M || ny < 0 || ny >= N)
                continue;

            // Determine if door is open
            int door_open;
            if (i < 2) { // east-west movement (dx != 0)
                door_open = (s == 1); // open when toggled
            } else { // north-south movement (dy != 0)
                door_open = (s == 0); // open when not toggled
            }

            if (door_open) {
                if (d + 1 < dist[nx][ny][s]) {
                    dist[nx][ny][s] = d + 1;
                    deque[back++] = (Node){nx, ny, s};
                }
            }
        }
    }

    int ans = dist[M-1][N-1][0];
    if (dist[M-1][N-1][1] < ans)
        ans = dist[M-1][N-1][1];

    if (ans == INT_MAX)
        printf("Impossible\n");
    else
        printf("%d\n", ans);

    return 0;
}

#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAXM 105
#define MAXN 105
#define INF 0x3f3f3f3f

int M, N, K;
int has_switch[MAXM][MAXN];
int dist[MAXM][MAXN][2];

// BFS with deque or Dijkstra - all edges cost 1, use BFS
#include <limits.h>

typedef struct { int x, y, p; } State;

int main() {
    scanf("%d %d", &M, &N);
    scanf("%d", &K);
    for (int i = 0; i < K; i++) {
        int x, y;
        scanf("%d %d", &x, &y);
        has_switch[x][y] = 1;
    }

    memset(dist, 0x3f, sizeof(dist));

    // BFS queue
    int cap = MAXM * MAXN * 2 * 10;
    State *queue = malloc(sizeof(State) * cap);
    int head = 0, tail = 0;

    dist[1][1][0] = 0;
    queue[tail++] = (State){1, 1, 0};

    int dx[] = {1, -1, 0, 0};
    int dy[] = {0, 0, 1, -1};
    // 0,1 are EW moves; 2,3 are NS moves

    while (head < tail) {
        State cur = queue[head++];
        int x = cur.x, y = cur.y, p = cur.p;
        int d = dist[x][y][p];

        // Move
        for (int i = 0; i < 4; i++) {
            int nx = x + dx[i], ny = y + dy[i];
            if (nx < 1 || nx > M || ny < 1 || ny > N) continue;
            // Check if door is open
            int open = 0;
            if (i < 2) { // EW door, open when p=1
                open = (p == 1);
            } else { // NS door, open when p=0
                open = (p == 0);
            }
            if (!open) continue;
            if (dist[nx][ny][p] > d + 1) {
                dist[nx][ny][p] = d + 1;
                queue[tail++] = (State){nx, ny, p};
            }
        }

        // Press switch
        if (has_switch[x][y]) {
            int np = 1 - p;
            if (dist[x][y][np] > d + 1) {
                dist[x][y][np] = d + 1;
                queue[tail++] = (State){x, y, np};
            }
        }
    }

    int ans = INF;
    if (dist[M][N][0] < ans) ans = dist[M][N][0];
    if (dist[M][N][1] < ans) ans = dist[M][N][1];

    if (ans == INF) printf("impossible\n");
    else printf("%d\n", ans);

    free(queue);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

static ll minll(ll a, ll b) { return a < b ? a : b; }

int main(void) {
    int M, N, K;
    if (scanf("%d %d %d", &M, &N, &K) != 3) return 0;

    /* hasSwitch[x][y], 1-based */
    char *hasSwitch = (char *)calloc((size_t)(M + 1) * (N + 1), sizeof(char));
    if (!hasSwitch) return 0;

    for (int i = 0; i < K; ++i) {
        int x, y;
        scanf("%d %d", &x, &y);
        if (1 <= x && x <= M && 1 <= y && y <= N)
            hasSwitch[x * (N + 1) + y] = 1;
    }

    const ll INF = (ll)4e18;

    /*
      State = (x, y, p)
      p = 0: current global door state is initial
             horizontal closed, vertical open
      p = 1: toggled odd times
             horizontal open, vertical closed

      Distances:
      d0[x][y] = min time to reach (x,y) with parity 0
      d1[x][y] = min time to reach (x,y) with parity 1

      Since all edge costs are 1 and transitions only depend on state,
      shortest paths satisfy simple monotone recurrences.

      Key observation:
      In parity 0, only vertical moves are possible.
      In parity 1, only horizontal moves are possible.
      A switch toggles parity at cost 1.

      Thus movement consists of alternating vertical segments in parity 0
      and horizontal segments in parity 1, with toggles only at switch rooms.
    */

    ll *d0 = (ll *)malloc((size_t)(M + 1) * (N + 1) * sizeof(ll));
    ll *d1 = (ll *)malloc((size_t)(M + 1) * (N + 1) * sizeof(ll));
    if (!d0 || !d1) return 0;

    for (int x = 1; x <= M; ++x) {
        for (int y = 1; y <= N; ++y) {
            d0[x * (N + 1) + y] = INF;
            d1[x * (N + 1) + y] = INF;
        }
    }

    d0[1 * (N + 1) + 1] = 0;
    if (hasSwitch[1 * (N + 1) + 1]) d1[1 * (N + 1) + 1] = 1;

    /*
      Relaxation by rows/columns repeatedly is enough, but we can do much better.

      Because:
      - In parity 0, within a fixed column x, all rooms reachable from any parity-0
        source in that column have cost source + |dy|.
      - In parity 1, within a fixed row y, all rooms reachable from any parity-1
        source in that row have cost source + |dx|.

      Toggling at switches transfers between d0 and d1 with +1.

      We perform dynamic propagation until no improvement.
      Since all transitions are of special line-distance form, use repeated scans.
      Constraints are not given, so keep implementation robust but reasonably efficient.

      We'll use Bellman-Ford-like closure on line transforms:
      Each iteration:
        1) toggle via switches
        2) propagate d0 vertically in each column
        3) propagate d1 horizontally in each row
      Distances only decrease; after enough passes they stabilize.

      In fact, because each full pass accounts for one more alternation block,
      at most M+N passes are needed, but typically far fewer.
    */

    int maxPass = M + N + 5;
    for (int pass = 0; pass < maxPass; ++pass) {
        int changed = 0;

        /* Toggle at switch rooms */
        for (int x = 1; x <= M; ++x) {
            for (int y = 1; y <= N; ++y) {
                if (!hasSwitch[x * (N + 1) + y]) continue;
                ll a = d0[x * (N + 1) + y];
                ll b = d1[x * (N + 1) + y];
                if (a + 1 < d1[x * (N + 1) + y]) {
                    d1[x * (N + 1) + y] = a + 1;
                    changed = 1;
                }
                if (b + 1 < d0[x * (N + 1) + y]) {
                    d0[x * (N + 1) + y] = b + 1;
                    changed = 1;
                }
            }
        }

        /* Propagate d0 vertically in each column */
        for (int x = 1; x <= M; ++x) {
            for (int y = 2; y <= N; ++y) {
                ll prev = d0[x * (N + 1) + (y - 1)];
                if (prev + 1 < d0[x * (N + 1) + y]) {
                    d0[x * (N + 1) + y] = prev + 1;
                    changed = 1;
                }
            }
            for (int y = N - 1; y >= 1; --y) {
                ll next = d0[x * (N + 1) + (y + 1)];
                if (next + 1 < d0[x * (N + 1) + y]) {
                    d0[x * (N + 1) + y] = next + 1;
                    changed = 1;
                }
            }
        }

        /* Propagate d1 horizontally in each row */
        for (int y = 1; y <= N; ++y) {
            for (int x = 2; x <= M; ++x) {
                ll prev = d1[(x - 1) * (N + 1) + y];
                if (prev + 1 < d1[x * (N + 1) + y]) {
                    d1[x * (N + 1) + y] = prev + 1;
                    changed = 1;
                }
            }
            for (int x = M - 1; x >= 1; --x) {
                ll next = d1[(x + 1) * (N + 1) + y];
                if (next + 1 < d1[x * (N + 1) + y]) {
                    d1[x * (N + 1) + y] = next + 1;
                    changed = 1;
                }
            }
        }

        if (!changed) break;
    }

    ll ans = minll(d0[M * (N + 1) + N], d1[M * (N + 1) + N]);
    if (ans >= INF / 2) {
        printf("-1\n");
    } else {
        printf("%lld\n", ans);
    }

    free(hasSwitch);
    free(d0);
    free(d1);
    return 0;
}

#include <bits/stdc++.h>
