int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int M, N;
    cin >> M >> N;

    // grid: 1-indexed, extra rows/cols for boundaries
    // row y, col x
    vector<vector<bool>> eastWest(M + 2, vector<bool>(N + 2, false)); // east-west doors: closed initially
    vector<vector<bool>> northSouth(M + 2, vector<bool>(N + 2, false)); // north-south doors: open initially

    // Read input: y from south (1..N), x from west (1..M)
    // eastWest[y][x] = door between (x,y) and (x+1,y)
    for (int y = 1; y <= N; ++y) {
        for (int x = 1; x <= M - 1; ++x) {
            int val;
            cin >> val;
            eastWest[y][x] = (val == 1);
        }
    }
    // northSouth[y][x] = door between (x,y) and (x,y+1)
    for (int y = 1; y <= N - 1; ++y) {
        for (int x = 1; x <= M; ++x) {
            int val;
            cin >> val;
            northSouth[y][x] = (val == 1);
        }
    }

    // dist[state][y][x] : state 0 = not toggled, 1 = toggled
    const int INF = 1e9;
    vector<vector<vector<int>>> dist(2, vector<vector<int>>(N + 2, vector<int>(M + 2, INF)));

    // priority queue: (time, state, y, x)
    // state 0 = original, state 1 = toggled
    priority_queue<tuple<int, int, int, int>, vector<tuple<int, int, int, int>>, greater<>> pq;

    dist[0][1][1] = 0;
    pq.push({0, 0, 1, 1});

    // directions: east, west, north, south (dx, dy)
    int dx[] = {1, -1, 0, 0};
    int dy[] = {0, 0, 1, -1};

    while (!pq.empty()) {
        auto [time, state, y, x] = pq.top();
        pq.pop();

        if (time != dist[state][y][x]) continue;

        if (x == M && y == N) {
            cout << time << '\n';
            return 0;
        }

        // Option 1: move to adjacent room if door is open
        for (int dir = 0; dir < 4; ++dir) {
            int nx = x + dx[dir];
            int ny = y + dy[dir];
            if (nx < 1 || nx > M || ny < 1 || ny > N) continue;

            bool doorOpen = false;
            if (dir == 0) { // east: door between (x,y) and (x+1,y)
                bool orig = eastWest[y][x];
                doorOpen = state ? !orig : orig;
            } else if (dir == 1) { // west: door between (x-1,y) and (x,y)
                bool orig = eastWest[y][x-1];
                doorOpen = state ? !orig : orig;
            } else if (dir == 2) { // north: door between (x,y) and (x,y+1)
                bool orig = northSouth[y][x];
                doorOpen = state ? !orig : orig;
            } else if (dir == 3) { // south: door between (x,y-1) and (x,y)
                bool orig = northSouth[y-1][x];
                doorOpen = state ? !orig : orig;
            }

            if (doorOpen && dist[state][ny][nx] > time + 1) {
                dist[state][ny][nx] = time + 1;
                pq.push({time + 1, state, ny, nx});
            }
        }

        // Option 2: toggle if there is a switch in (x,y)
        // toggle costs 1 minute, changes state
        int newState = 1 - state;
        if (dist[newState][y][x] > time + 1) {
            dist[newState][y][x] = time + 1;
            pq.push({time + 1, newState, y, x});
        }
    }

    cout << -1 << '\n';
    return 0;
}

