    for (int i = 0; i < K; i++) {
        int x, y;
        cin >> x >> y;
        hasSwitch[x][y] = true;
    }

    // BFS
    // state: (x, y, door_state)
    // door_state 0: EW closed, NS open
    // door_state 1: EW open, NS closed

    vector<vector<vector<int>>> dist(M+1, vector<vector<int>>(N+1, vector<int>(2, INT_MAX)));

    queue<tuple<int,int,int>> q;
    dist[1][1][0] = 0;
    q.push({1, 1, 0});

    // dx, dy for movements
    // EW: east (+1,0), west (-1,0) - need door_state==1
    // NS: north (0,+1), south (0,-1) - need door_state==0

    while (!q.empty()) {
        auto [x, y, ds] = q.front();
        q.pop();

        int d = dist[x][y][ds];

        if (x == M && y == N) {
            cout << d << endl;
            return 0;
        }

        // Try moving
        // EW movement (needs ds == 1)
        if (ds == 1) {
            int nx, ny;
            // East
            nx = x+1; ny = y;
            if (nx >= 1 && nx <= M && dist[nx][ny][ds] == INT_MAX) {
                dist[nx][ny][ds] = d+1;
                q.push({nx, ny, ds});
            }
            // West
            nx = x-1; ny = y;
            if (nx >= 1 && nx <= M && dist[nx][ny][ds] == INT_MAX) {
                dist[nx][ny][ds] = d+1;
                q.push({nx, ny, ds});
            }
        }
        // NS movement (needs ds == 0)
        if (ds == 0) {
            int nx, ny;
            nx = x; ny = y+1;
            if (ny >= 1 && ny <= N && dist[nx][ny][ds] == INT_MAX) {
                dist[nx][ny][ds] = d+1;
                q.push({nx, ny, ds});
            }
            nx = x; ny = y-1;
            if (ny >= 1 && ny <= N && dist[nx][ny][ds] == INT_MAX) {
                dist[nx][ny][ds] = d+1;
                q.push({nx, ny, ds});
            }
        }

        // Try switch
        if (hasSwitch[x][y] && dist[x][y][1-ds] == INT_MAX) {
            dist[x][y][1-ds] = d+1;
            q.push({x, y, 1-ds});
        }
    }

    cout << "impossible" << endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long M, N, K;
    if (!(cin >> M >> N >> K)) return 0;

    // Rooms with switches do not affect the answer:
    // pressing any switch toggles all doors globally, so only the current parity matters.
    // State = (x, y, p), where p=0 means initial door configuration,
    // p=1 means toggled configuration.
    //
    // Initial:
    //   horizontal doors closed, vertical doors open
    // Toggled:
    //   horizontal doors open, vertical doors closed
    //
    // Thus:
    // - with p=0, only vertical moves are possible
    // - with p=1, only horizontal moves are possible
    //
    // To move in both directions, at least one switch press is needed.
    // Since pressing can be done in any room containing a switch, and toggling is global,
    // the exact locations only matter in whether at least one switch exists at all.
    //
    // If M=1 and N=1 => already at target, answer 0.
    // If only vertical travel needed (M=1), answer N-1.
    // If only horizontal travel needed (N=1):
    //   need one press first, then move horizontally => possible iff K>0, answer 1 + (M-1)
    // If both M>1 and N>1:
    //   need at least one press to enable horizontal movement, and one parity change total.
    //   Best is:
    //     move vertically to some switch, press, move horizontally to column M, move vertically as needed.
    //   But since with p=1 vertical moves are impossible, all vertical movement must be done before/after presses.
    //   Starting in p=0, we can move vertically first, then press once, then move horizontally.
    //   To also end at row N, we must already be at row N before the press.
    //   So route: move vertically from (1,1) to (1,N): N-1, press: 1, move horizontally to (M,N): M-1.
    //   This is possible iff there exists at least one switch somewhere on column 1 reachable before pressing,
    //   i.e. in some room (1, y). However, after moving vertically to row of a switch, pressing there fixes parity,
    //   and then no more vertical moves. Therefore to end at row N, the switch must be in room (1, N).
    //
    // Symmetrically, another way is impossible because initially horizontal moves are blocked.
    //
    // Therefore:
    // - For M>1 and N>1, possible iff room (1,N) has a switch.
    //
    // Input only gives switch rooms; duplicates do not matter.

    set<pair<long long,long long>> sw;
    for (long long i = 0; i < K; ++i) {
        long long x, y;
        cin >> x >> y;
        sw.insert({x, y});
    }

    if (M == 1 && N == 1) {
        cout << 0 << '\n';
        return 0;
    }

    if (M == 1) {
        cout << (N - 1) << '\n';
        return 0;
    }

    if (N == 1) {
        if (K == 0) {
            cout << -1 << '\n';
        } else {
            cout << M << '\n'; // press once + (M-1) horizontal moves
        }
        return 0;
    }

    if (sw.count({1, N})) {
        cout << (N - 1) + 1 + (M - 1) << '\n';
    } else {
        cout << -1 << '\n';
    }

    return 0;
}

import java.io.*;
import java.util.*;

public class Main {
    static final int INF = Integer.MAX_VALUE / 2;
    static int M, N;
    static int[][][] dist;
    // Directions: east, west, north, south
    static int[] dx = {1, -1, 0, 0};
    static int[] dy = {0, 0, 1, -1};

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        M = Integer.parseInt(st.nextToken());
        N = Integer.parseInt(st.nextToken());

        // dist[x][y][state] : state 0 = not toggled, 1 = toggled
        dist = new int[M+1][N+1][2];
        for (int i = 1; i <= M; i++) {
            for (int j = 1; j <= N; j++) {
                Arrays.fill(dist[i][j], INF);
            }
        }

        // 0-1 BFS using deque
        Deque<int[]> dq = new ArrayDeque<>();
        dist[1][1][0] = 0;
        dq.addFirst(new int[]{1, 1, 0});

        while (!dq.isEmpty()) {
            int[] cur = dq.pollFirst();
            int x = cur[0], y = cur[1], state = cur[2];
            int d = dist[x][y][state];

            // Option 1: move to adjacent room through a door if open
            for (int dir = 0; dir < 4; dir++) {
                int nx = x + dx[dir];
                int ny = y + dy[dir];
                if (nx < 1 || nx > M || ny < 1 || ny > N) continue;

                // Determine if door is open:
                // east-west (dir 0 or 1) -> initially closed, so open if toggled (state=1)
                // north-south (dir 2 or 3) -> initially open, so open if NOT toggled (state=0)
                boolean doorOpen;
                if (dir == 0 || dir == 1) {
                    doorOpen = (state == 1);
                } else {
                    doorOpen = (state == 0);
                }

                if (doorOpen) {
                    if (dist[nx][ny][state] > d + 1) {
                        dist[nx][ny][state] = d + 1;
                        dq.addLast(new int[]{nx, ny, state});
                    }
                }
            }

            // Option 2: press switch in current room (if there is one)
            // We assume every room has a switch. Toggling takes 1 minute.
            int newState = 1 - state;
            if (dist[x][y][newState] > d + 1) {
                dist[x][y][newState] = d + 1;
                dq.addLast(new int[]{x, y, newState});
            }
        }

        int ans = Math.min(dist[M][N][0], dist[M][N][1]);
        if (ans == INF) {
            System.out.println("IMPOSSIBLE");
        } else {
            System.out.println(ans);
        }
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int M = sc.nextInt(), N = sc.nextInt();
        boolean[][] hasSwitch = new boolean[M+1][N+1];
        // Read grid: N lines, each M chars
        // Assume y=N is first line (northernmost), y=1 is last line
        String[] grid = new String[N];
        for (int i = 0; i < N; i++) grid[i] = sc.next();
        for (int y = 1; y <= N; y++) {
            String row = grid[N - y]; // y=1 is southernmost = last line
            for (int x = 1; x <= M; x++) {
                if (row.charAt(x-1) == 'S') hasSwitch[x][y] = true;
            }
        }

        int[][][] dist = new int[M+1][N+1][2];
        for (int[][] a : dist) for (int[] b : a) Arrays.fill(b, Integer.MAX_VALUE);
        Queue<int[]> queue = new LinkedList<>();
        dist[1][1][0] = 0;
        queue.add(new int[]{1, 1, 0, 0});
        int[] dx = {1,-1,0,0};
        int[] dy = {0,0,1,-1};

        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int x = cur[0], y = cur[1], d = cur[2], t = cur[3];
            if (t > dist[x][y][d]) continue;
            // Try moving
            for (int dir = 0; dir < 4; dir++) {
                int nx = x+dx[dir], ny = y+dy[dir];
                if (nx<1||nx>M||ny<1||ny>N) continue;
                boolean ew = (dir==0||dir==1);
                boolean open = (ew && d==1) || (!ew && d==0);
                if (open && t+1 < dist[nx][ny][d]) {
                    dist[nx][ny][d] = t+1;
                    queue.add(new int[]{nx,ny,d,t+1});
                }
            }
            // Press switch
            if (hasSwitch[x][y] && t+1 < dist[x][y][1-d]) {
                dist[x][y][1-d] = t+1;
                queue.add(new int[]{x,y,1-d,t+1});
            }
        }
        int ans = Math.min(dist[M][N][0], dist[M][N][1]);
        if (ans == Integer.MAX_VALUE) System.out.println("impossible");
        else System.out.println(ans);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static class Edge {
        int to, w;
        Edge(int to, int w) {
            this.to = to;
            this.w = w;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int M, N;
        try {
            M = fs.nextInt();
            N = fs.nextInt();
        } catch (Exception e) {
            return;
        }

        int K = fs.nextInt(); // number of rooms containing switches

        boolean[][] hasSwitch = new boolean[M + 1][N + 1];
        for (int i = 0; i < K; i++) {
            int x = fs.nextInt();
            int y = fs.nextInt();
            if (1 <= x && x <= M && 1 <= y && y <= N) {
                hasSwitch[x][y] = true;
            }
        }

        // State: (x, y, p)
        // p = 0 => original configuration:
        //        east-west doors closed, north-south doors open
        // p = 1 => toggled configuration:
        //        east-west doors open, north-south doors closed
        int totalStates = M * N * 2;
        List<Edge>[] graph = new ArrayList[totalStates];
        for (int i = 0; i < totalStates; i++) graph[i] = new ArrayList<>();

        for (int x = 1; x <= M; x++) {
            for (int y = 1; y <= N; y++) {
                for (int p = 0; p <= 1; p++) {
                    int id = id(x, y, p, N);

                    // Move north/south if those doors are open in this parity
                    boolean nsOpen = (p == 0);
                    boolean ewOpen = (p == 1);

                    if (nsOpen) {
                        if (y > 1) graph[id].add(new Edge(id(x, y - 1, p, N), 1));
                        if (y < N) graph[id].add(new Edge(id(x, y + 1, p, N), 1));
                    }
                    if (ewOpen) {
                        if (x > 1) graph[id].add(new Edge(id(x - 1, y, p, N), 1));
                        if (x < M) graph[id].add(new Edge(id(x + 1, y, p, N), 1));
                    }

                    // Press switch if present: toggles all doors, costs 1 minute
                    if (hasSwitch[x][y]) {
                        graph[id].add(new Edge(id(x, y, 1 - p, N), 1));
                    }
                }
            }
        }

        long[] dist = new long[totalStates];
        Arrays.fill(dist, Long.MAX_VALUE / 4);
        PriorityQueue<long[]> pq = new PriorityQueue<>(Comparator.comparingLong(a -> a[0]));

        int start = id(1, 1, 0, N);
        dist[start] = 0;
        pq.add(new long[]{0, start});

        while (!pq.isEmpty()) {
            long[] cur = pq.poll();
            long d = cur[0];
            int u = (int) cur[1];
            if (d != dist[u]) continue;

            for (Edge e : graph[u]) {
                long nd = d + e.w;
                if (nd < dist[e.to]) {
                    dist[e.to] = nd;
                    pq.add(new long[]{nd, e.to});
                }
            }
        }

        long ans = Math.min(dist[id(M, N, 0, N)], dist[id(M, N, 1, N)]);
        if (ans >= Long.MAX_VALUE / 8) {
            System.out.println("Impossible");
        } else {
            System.out.println(ans);
        }
    }

    static int id(int x, int y, int p, int N) {
        return ((x - 1) * N + (y - 1)) * 2 + p;
    }
}
